  "2-5": {
    slides: [
      { type: "title", stage: "Unit 2 · Unit Review", eyebrow: "A1 · Ignite", title: "Unit Review", subtitle: "Talk briefly about family using everything you've learned. No new language today." },
      { type: "vocab", stage: "Quick Review", heading: "Family → Facts → Description → Questions", subheading: "Everything from this unit", items: [{ label: "family members" }, { label: "numbers" }, { label: "ages" }, { label: "appearance" }, { label: "personality" }], instruction: [["🗣️", "Answer fast, one word is fine."]] },
      { type: "message", stage: "Language Review", heading: "Who? → Facts → Description", subheading: "Your speaking structure", lines: ["This is my brother. His name is Alex. He is *15* years old. He is *tall and funny*."], instruction: [["👀", "Look at the structure."], ["🗣️", "Say it with me."]] },
      { type: "dialogue", stage: "Controlled Practice", heading: "Talk About the Profile", subheading: "Use a fictional profile to build sentences", turns: [{ who: "teacher", text: "Sophie, sister, 13, funny. Tell me about her." }, { who: "student", text: "This is my sister. Her name is Sophie. She is 13. She is funny." }], instruction: [["🗣️", "Build the sentence."]] },
      { type: "dialogue", stage: "Controlled Practice 2", heading: "One More Profile", subheading: "Same idea, new details", turns: [{ who: "teacher", text: "This is my family. This is my mom. Her name is Anna. She is 40 years old. She is friendly." }, { who: "teacher", text: "What's her name? How old is your brother?" }], instruction: [["🗣️", "Fill in your own details."]] },
      { type: "factorcap", stage: "Final Challenge: Round 1", heading: "True or Cap?", statements: [{ text: "Saying \"He is tall\" uses the verb have.", isTrue: false, explain: "Use is/are for descriptions like tall, funny, or nice -- have is for things like hair or siblings." }, { text: "You can use both is and has to describe the same person.", isTrue: true, explain: "Exactly -- \"She is friendly. She has long hair\" mixes both naturally." }, { text: "Asking \"How many brothers do you have?\" is a way to ask about family size.", isTrue: true, explain: "That's exactly what that question means." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "thisorthat", stage: "Final Challenge: Round 2", heading: "Is or Has?", pairs: [["She is nice.", "She has nice."], ["He has short hair.", "He is short hair."], ["I have two brothers.", "I am two brothers."], ["She is funny.", "She has funny."]], instruction: [["🤔", "Pick the correct sentence."]] },
      { type: "factorcap", stage: "Final Challenge: Round 3", heading: "True or Cap? 2", statements: [{ text: "You can only describe family members, never friends.", isTrue: false, explain: "The same is/has patterns work for describing anyone, not just family." }, { text: "\"I have two brothers\" tells you how many siblings someone has.", isTrue: true, explain: "Exactly -- have plus a number is how you say how many." }, { text: "Asking about someone's family is considered rude in a first conversation.", isTrue: false, explain: "It's a normal, friendly topic once you already know someone a little." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "thisorthat", stage: "Final Challenge: Round 4", heading: "Is or Has? Round 2", pairs: [["He is friendly.", "He has friendly."], ["She has brown hair.", "She is brown hair."], ["They have one sister.", "They are one sister."], ["He is quiet.", "He has quiet."]], instruction: [["🤔", "Pick the correct sentence."]] },
      { type: "practice", stage: "Independent Check", heading: "Tell Me About Your Family", subheading: "Speak independently for 30-60 seconds", line: "This is my family. This is my ___. ___'s name is ___. ___ is ___.", instruction: [["🗣️", "Say the whole thing."], ["🙅", "No help this time."]] },
      { type: "landing", stage: "Unit Complete!", heading: "Unit 2 Complete!", caption: "You can name family members, give facts, describe people, answer questions, and talk about your family." },
    ],
  },
